{"findings":[{"tipo":"GC","causa_raiz":"Alocação excessiva de memória gerenciada em um único frame (~7.62 MB / 7.987.847 bytes), disparando uma coleta de lixo síncrona (GC.Collect) que pausou a CPU por 24.57ms. Isso é tipicamente causado por instanciação em massa sem pooling, concatenação intensiva de strings/logs dentro de loops, ou criação recorrente de arrays/coleções temporárias.","codigo_refatorado":"using System.Collections.Generic;
using UnityEngine;
using UnityEngine.Pool;

public class OptimizedSpawner : MonoBehaviour
{
    [SerializeField] private GameObject prefab;
    [SerializeField] private int defaultCapacity = 100;
    [SerializeField] private int maxPoolSize = 500;

    private ObjectPool<GameObject> pool;
    private readonly List<GameObject> activeObjects = new List<GameObject>();

    private void Awake()
    {
        pool = new ObjectPool<GameObject>(
            createFunc: () => Instantiate(prefab),
            actionOnGet: obj => obj.SetActive(true),
            actionOnRelease: obj => obj.SetActive(false),
            actionOnDestroy: obj => Destroy(obj),
            collectionCheck: false,
            defaultCapacity: defaultCapacity,
            maxSize: maxPoolSize
        );
    }

    public GameObject Spawn(Vector3 position, Quaternion rotation)
    {
        GameObject obj = pool.Get();
        obj.transform.SetPositionAndRotation(position, rotation);
        activeObjects.Add(obj);
        return obj;
    }

    public void Despawn(GameObject obj)
    {
        if (activeObjects.Remove(obj))
        {
            pool.Release(obj);
        }
    }

    public void DespawnAll()
    {
        for (int i = activeObjects.Count - 1; i >= 0; i--)
        {
            pool.Release(activeObjects[i]);
        }
        activeObjects.Clear();
    }
}","explicacao_didatica":"O Garbage Collector (coletor de lixo da Unity) precisa congelar a execução do jogo para limpar objetos descartados na memória quando alocamos muitos dados temporários de uma só vez (quase 8 MB no frame 1915). Para evitar essas travadas (stutters), utilizamos a técnica de Object Pooling: em vez de criar (Instantiate) e destruir (Destroy) objetos dinamicamente, nós os criamos previamente e apenas ativamos ou desativamos conforme a necessidade, reutilizando a mesma memória sem sobrecarregar o coletor de lixo."}],"dicas_level_design":null}

